async function collection(){
 let favSet=new Set();try{const [d,f]=await Promise.all([api("/api/collection"),api("/api/favorites").catch(()=>({favorites:[]}))]);state.user=d.user;state.cards=d.cards||[];favSet=new Set((f.favorites||[]).map(x=>x.instanceId))}catch(e){if(e.status===401)return authView("login","collection");throw e}
 const filters=["all","common","rare","epic","legendary","icon"],labels={icon:"ICON",legendary:"LEGENDARY",epic:"EPIC",rare:"RARE",common:"COMMON"},q=state.collectionSearch.trim().toLowerCase();
 const grouped=new Map();state.cards.forEach(c=>{const key=c.cardId||c.id||c.instanceId;const existing=grouped.get(key);if(existing){existing.quantity+=1;existing.favorite=existing.favorite||favSet.has(c.instanceId)}else grouped.set(key,{...c,quantity:1,favorite:favSet.has(c.instanceId)})});const uniqueCards=[...grouped.values()];
 const base=uniqueCards.filter(c=>(state.filter==="all"||c.rarity===state.filter)&&(!q||[c.name,c.club,c.nation,c.position,c.rarityLabel].some(v=>String(v||"").toLowerCase().includes(q))));
 const sorted=[...base].sort((a,b)=>state.collectionSort==="ovr"?Number(b.ovr||0)-Number(a.ovr||0):state.collectionSort==="rarity"?(rarityOrder[b.rarity]||0)-(rarityOrder[a.rarity]||0):state.collectionSort==="name"?String(a.name).localeCompare(String(b.name),"fr"):0);
 const groups=state.filter==="all"?["icon","legendary","epic","rare","common"]:[state.filter];
 const sections=groups.map(r=>{const cards=sorted.filter(c=>c.rarity===r);return cards.length?`<section class="collection-rarity-section"><div class="collection-rarity-head"><div><span class="eyebrow">${labels[r]}</span><h2>${labels[r]}</h2></div><strong>${String(cards.length).padStart(2,"0")} CARTE${cards.length>1?"S":""}</strong></div><div class="collection-card-grid">${cards.map(c=>`<div class="collection-card-item">${c.favorite?'<span class="collection-fav" title="Carte favorite" aria-label="Carte favorite">★</span>':''}${cardLink(c)}<span class="collection-quantity">${c.quantity} EXEMPLAIRE${c.quantity>1?"S":""}</span></div>`).join("")}</div></section>`:""}).join("");
 return `<div class="page collection-page"><section class="collection-showcase"><div class="collection-showcase-copy"><p class="eyebrow">FOOTVAULT / COLLECTION</p><h1>MA <span>COLLECTION</span></h1><p>Toutes tes cartes réunies au même endroit. Explore tes joueurs, compare les raretés et retrouve tes exemplaires.</p></div><div class="collection-showcase-mark"><span>FV</span><b>COLLECT<br>THE GAME</b></div></section><section class="collection-overview"><div><span>CARTES POSSÉDÉES</span><strong>${state.cards.length.toLocaleString('fr-FR')}</strong><small>exemplaires dans ton Vault</small></div><div><span>JOUEURS DIFFÉRENTS</span><strong>${uniqueCards.length.toLocaleString('fr-FR')}</strong><small>cartes uniques</small></div><div><span>RARETÉS</span><strong>${new Set(state.cards.map(c=>c.rarity)).size}</strong><small>niveaux présents</small></div><div><span>DOUBLONS</span><strong>${Math.max(0,state.cards.length-uniqueCards.length).toLocaleString('fr-FR')}</strong><small>exemplaires supplémentaires</small></div></section><section class="collection-progress-panel"><div class="collection-progress-title"><div><p class="eyebrow">ÉTAT DE LA COLLECTION</p><h2>TES RARETÉS</h2></div><strong>${uniqueCards.length} CARTES UNIQUES</strong></div><div class="collection-rarity-grid">${["common","rare","epic","legendary","icon"].map(r=>{const names={common:"COMMON",rare:"RARE",epic:"EPIC",legendary:"LEGENDARY",icon:"ICON"};const owned=uniqueCards.filter(c=>c.rarity===r).length;return `<div class="collection-rarity-mini is-${r}" title="${owned} carte(s) ${names[r]} sur ${uniqueCards.length} cartes uniques"><div><span>${names[r]}</span><b>${owned}</b></div><i><em style="width:${uniqueCards.length?Math.max(owned?3:0,Math.round(owned/uniqueCards.length*100)):0}%"></em></i></div>`}).join("")}</div></section><div class="collection-toolbar"><div class="filters">${filters.map(f=>`<button class="filter ${state.filter===f?"active":""}" data-filter="${f}">${f==="all"?"Toutes":f==="icon"?"Icon":f[0].toUpperCase()+f.slice(1)}</button>`).join("")}</div><div class="collection-tools"><input id="collectionSearch" class="collection-search" aria-label="Rechercher dans ma collection" value="${esc(state.collectionSearch)}" placeholder="Rechercher joueur, club, pays..." /><select id="collectionSort" class="collection-sort" aria-label="Trier la collection"><option value="recent" ${state.collectionSort==="recent"?"selected":""}>Récent</option><option value="ovr" ${state.collectionSort==="ovr"?"selected":""}>OVR décroissant</option><option value="rarity" ${state.collectionSort==="rarity"?"selected":""}>Rareté</option><option value="name" ${state.collectionSort==="name"?"selected":""}>Nom A → Z</option></select></div></div>${sections||`<section class="collection-rarity-section"><div class="empty">AUCUNE CARTE NE CORRESPOND À TA RECHERCHE.</div></section>`}</div>`;
}
