 // Défis thématiques (lib/challenges.js) : en cours, réussis à récupérer, à venir.
 const fmtDate=d=>new Date(d).toLocaleString('fr-FR',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
 const challengeCard=(c,state)=>{const pct=Math.min(100,c.target?c.progress/c.target*100:0),ready=c.claimable;return '<article class="mission vault-mission challenge-card '+(ready?'is-ready ':'')+(c.claimed?'mission-completed':'')+'"><div class="mission-head"><div><p class="eyebrow">'+(state==='upcoming'?'À VENIR · DÈS LE '+esc(fmtDate(c.startsAt).toUpperCase()):state==='ended'?'TERMINÉ · À RÉCUPÉRER':'DÉFI · JUSQU’AU '+esc(fmtDate(c.endsAt).toUpperCase()))+'</p><h3>'+esc(c.title)+'</h3></div><b>+'+money(c.reward.coins)+' FC<br>+'+money(c.reward.xp)+' XP</b></div><p>'+esc(c.description)+'</p>'+(c.competitionName||c.packName?'<p class="challenge-scope">'+esc(c.competitionName?'Championnat : '+c.competitionName:'Pack : '+c.packName)+'</p>':'')+(state==='upcoming'?'':'<div class="vault-mission-progress"><div class="progress"><i style="width:'+pct+'%"></i></div><span>'+c.progress+'/'+c.target+'</span></div>')+'<button class="btn '+(ready?'btn-gold':'btn-outline')+'" '+(ready?'data-challenge="'+esc(c.id)+'"':'disabled')+'>'+(c.claimed?'RÉCUPÉRÉ ✓':ready?'RÉCUPÉRER':state==='upcoming'?'BIENTÔT':'EN COURS')+'</button></article>';};
 const challengeList=[...(challengeData.ended||[]).map(c=>challengeCard(c,'ended')),...(challengeData.current||[]).map(c=>challengeCard(c,'current')),...(challengeData.upcoming||[]).map(c=>challengeCard(c,'upcoming'))];
 // Sets thématiques (lib/card-sets.js) : cartes à réunir, récompense unique, plafond quotidien de FC.
 const setCard=x=>{const pct=Math.min(100,x.total?x.owned/x.total*100:0);return '<article class="mission vault-mission set-card '+(x.claimable?'is-ready ':'')+(x.claimed?'mission-completed':'')+'"><div class="mission-head"><div><p class="eyebrow">SET '+esc(x.reward.tier)+' · '+x.total+' CARTES</p><h3>'+esc(x.name)+'</h3></div><b>+'+money(x.reward.coins)+' FC<br>+'+money(x.reward.xp)+' XP</b></div><p>'+esc(x.description)+'</p><div class="vault-mission-progress"><div class="progress"><i style="width:'+pct+'%"></i></div><span>'+x.owned+'/'+x.total+'</span></div><details class="set-cards"><summary>VOIR LES CARTES</summary><ul>'+x.cards.map(c=>'<li class="'+(c.owned?'is-owned':'is-missing')+'"><span aria-hidden="true">'+(c.owned?'✓':'○')+'</span> '+esc(c.name)+' <small>'+esc(c.club)+' · '+esc(c.season)+'<span class="sr-only">'+(c.owned?' · possédée':' · manquante')+'</span></small></li>').join('')+'</ul></details>'+(x.blockedByCap?'<p class="set-cap-note" role="status">Plafond quotidien atteint ('+money(setsData.dailyCap)+' FC de sets par jour) : ton set t’attend, reviens demain.</p>':'')+'<button class="btn '+(x.claimable?'btn-gold':'btn-outline')+'" '+(x.claimable?'data-set-claim="'+esc(x.id)+'"':'disabled')+'>'+(x.claimed?'RÉCUPÉRÉ ✓':x.claimable?'RÉCUPÉRER':x.blockedByCap?'REVIENS DEMAIN':'EN COURS')+'</button></article>';};
 const setList=[...(setsData.sets||[])].sort((a,b)=>(b.claimable-a.claimable)||(a.claimed-b.claimed)||(b.owned/b.total-a.owned/a.total)).map(setCard);
 const setSection=setList.length?'<section class="section vault-missions-section set-section"><div class="section-head vault-section-head"><div><p class="eyebrow">SETS THÉMATIQUES</p><h2>RÉUNIS LES CARTES</h2></div><p>Possède toutes les cartes d’un set pour gagner une récompense unique. Récompenses de sets : '+money(setsData.dailyCap)+' FC maximum par jour (il te reste '+money(setsData.remainingToday)+' FC aujourd’hui).</p></div><div class="mission-grid vault-mission-grid">'+setList.join('')+'</div></section>':'';
