// Classement des collectionneurs (#classement) : score pondéré par rareté, général ou de la semaine.
async function ranking(q){
 const period=q?.get('periode')==='semaine'?'week':'all';
 const d=await api('/api/leaderboard?period='+period);
 const pts=d.points||{},RL={common:'Common',rare:'Rare',epic:'Epic',legendary:'Legendary',icon:'Icon'};
 const top=d.top||[],podium=top.slice(0,3),rest=top.slice(3);
 const week=d.week?new Date(d.week.start).toLocaleDateString('fr-FR',{day:'numeric',month:'long'}):'';
 const row=p=>'<tr class="'+(p.me?'is-me':'')+'"><td class="rank-pos">'+p.rank+'</td><td class="rank-name">'+esc(p.name)+(p.me?' <span class="rank-you">TOI</span>':'')+'</td><td>'+money(p.uniqueCards)+'</td><td>'+money(p.topCards)+'</td><td class="rank-score">'+money(p.score)+'</td></tr>';
 const medal=['🥇','🥈','🥉'];
 const me=d.me;
 // Récompenses du classement de la semaine : barème et récompenses du joueur à récupérer.
 const weekLabel=k=>new Date(k+'T12:00:00Z').toLocaleDateString('fr-FR',{day:'numeric',month:'long'});
 const ord=n=>n+(n===1?'er':'e');
 const claimable=(d.myRewards||[]).filter(r=>!r.claimed);
 const rewardsHtml='<section class="ranking-rewards"><div><p class="eyebrow">CHAQUE LUNDI À MINUIT</p><h2>RÉCOMPENSES DE LA SEMAINE</h2><p>Le classement de la semaine est figé chaque lundi : les 50 premiers gagnent des FOOTCOINS et de l’XP (ex æquo : même récompense).</p></div><ul>'+(d.rewards||[]).map(t=>'<li><b>'+(t.from===t.to?ord(t.from):t.from+'e – '+t.to+'e')+'</b><span>'+money(t.coins)+' FC · '+money(t.xp)+' XP</span></li>').join('')+'</ul></section>';
 const claimHtml=claimable.map(r=>'<section class="ranking-claim"><div><span>SEMAINE DU '+esc(weekLabel(r.week).toUpperCase())+'</span><strong>Tu as fini '+ord(r.rank)+' !</strong><small>'+money(r.score)+' pts · +'+money(r.reward.coins)+' FC · +'+money(r.reward.xp)+' XP</small></div><button class="btn btn-gold" type="button" data-lb-claim="'+esc(r.week)+'">RÉCUPÉRER</button></section>').join('');
 return '<div class="page ranking-page">'
 +'<section class="ranking-hero"><div><p class="eyebrow">FOOTVAULT / CLASSEMENT</p><h1>LES <span>COLLECTIONNEURS.</span></h1><p class="lead">Chaque joueur différent de ta collection rapporte des points selon sa rareté. Les doublons ne comptent pas.</p>'
 +'<ul class="ranking-points">'+Object.entries(pts).map(([r,v])=>'<li class="rp-'+esc(r)+'"><b>'+esc(RL[r]||r)+'</b><span>'+v+' pt'+(v>1?'s':'')+'</span></li>').join('')+'</ul></div>'
 +'<div class="ranking-tabs" role="tablist"><a role="tab" aria-selected="'+(period==='all')+'" class="'+(period==='all'?'active':'')+'" href="#classement">GÉNÉRAL</a><a role="tab" aria-selected="'+(period==='week')+'" class="'+(period==='week'?'active':'')+'" href="#classement?periode=semaine">CETTE SEMAINE</a></div></section>'
 +(me?'<section class="ranking-me"><span>TON RANG</span><strong>'+(me.rank?me.rank+'<small>/'+money(d.players)+'</small>':'—')+'</strong><div><b>'+money(me.score)+' pts</b><small>'+money(me.uniqueCards)+' joueurs différents'+(period==='week'?' obtenus cette semaine':'')+'</small></div>'+(me.rank?'':'<a class="btn btn-gold" href="#packs">OUVRIR UN PACK</a>')+'</section>':'<section class="ranking-me"><span>TON RANG</span><strong>—</strong><div><small>Connecte-toi pour apparaître au classement.</small></div><a class="btn btn-gold" href="#auth?mode=login&next=classement">SE CONNECTER</a></section>')
 +claimHtml+(period==='week'?'<p class="ranking-note">Cartes obtenues depuis le lundi '+esc(week)+' à minuit (heure de Paris). Nouveau classement chaque lundi.</p>':'')
 +(top.length?'<section class="ranking-podium">'+[0,1,2].map(i=>{const p=podium[i];return p?'<article class="podium-'+(i+1)+(p.me?' is-me':'')+'"><span class="podium-medal" aria-hidden="true">'+medal[i]+'</span><b>'+esc(p.name)+'</b><strong>'+money(p.score)+' pts</strong><small>'+money(p.uniqueCards)+' joueurs · '+money(p.topCards)+' Legendary/Icon</small><i class="podium-step" aria-hidden="true">'+(i+1)+'</i></article>':'<article class="podium-'+(i+1)+' podium-empty"><span class="podium-medal" aria-hidden="true">'+medal[i]+'</span><b>Place libre</b><small>Ouvre des packs pour la prendre !</small><i class="podium-step" aria-hidden="true">'+(i+1)+'</i></article>';}).join('')+'</section>'
 +(rest.length?'<div class="ranking-table-wrap"><table class="ranking-table"><thead><tr><th>#</th><th>COLLECTIONNEUR</th><th>JOUEURS</th><th>LEG./ICON</th><th>POINTS</th></tr></thead><tbody>'+rest.map(row).join('')+'</tbody></table></div>':'')
 :'<div class="empty">'+(period==='week'?'Personne n’a encore obtenu de carte cette semaine : ouvre un pack pour prendre la tête !':'Aucun collectionneur classé pour le moment.')+'</div>')
 +rewardsHtml+'<p class="ranking-note">'+money(d.players)+' collectionneur'+(d.players>1?'s':'')+' classé'+(d.players>1?'s':'')+'. Les 50 premiers sont affichés ; les cartes offertes par l’équipe ne comptent pas. Mise à jour toutes les minutes.</p>'
 +'</div>';
}

// Profil joueur (#profil) : identité, collection, progression et historique (GET /api/profile).
function favoriteShowcase(favs){
 const slots=Array.from({length:5},(_,i)=>favs[i]);
 return '<section class="profile-panel profile-favorites"><div class="profile-favorites-head"><div><p class="eyebrow">VITRINE</p><h2>MES CARTES FAVORITES</h2></div><small>'+favs.length+' / 5</small></div>'
  +(favs.length?'':'<p class="profile-empty">Choisis jusqu’à 5 cartes à mettre en avant : ouvre une carte de ta collection et touche « ☆ Ajouter aux favoris ».</p>')
  +'<div class="profile-fav-row">'+slots.map(c=>c?'<div class="profile-fav-card"><a href="#card?id='+encodeURIComponent(c.instanceId)+'" aria-label="'+esc(c.name)+'">'+cardMarkup(c)+'</a><button class="profile-fav-remove" type="button" data-fav-remove="'+esc(c.instanceId)+'" aria-label="Retirer '+esc(c.name)+' des favorites" title="Retirer des favorites">×</button></div>':'<a class="profile-fav-empty" href="#collection"><span>+</span><small>Ajouter une favorite</small></a>').join('')+'</div></section>';
}
async function profile(){
 let d;try{d=await api('/api/profile')}catch(e){if(e.status===401)return authView('login','profil');throw e}
 const p=d.profile,c=d.collection,g=d.progress||{},h=d.history||[];
 const xpPct=Math.min(100,p.xpToNext?p.currentXp/p.xpToNext*100:0),since=p.memberSince?new Date(p.memberSince).toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'}):'—';
 const RL={common:'Common',rare:'Rare',epic:'Epic',legendary:'Legendary',icon:'Icon'},maxR=Math.max(1,...c.rarities.map(r=>r.count));
 const kpi=(label,value,sub)=>'<article class="profile-kpi"><span>'+label+'</span><strong>'+value+'</strong>'+(sub?'<small>'+sub+'</small>':'')+'</article>';
 const when=x=>new Date(x).toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
 return '<div class="page profile-page">'
 +'<section class="profile-hero"><div class="profile-avatar" aria-hidden="true">'+esc(initials(p.name))+'</div><div class="profile-id"><p class="eyebrow">PROFIL JOUEUR</p><h1>'+esc(p.name)+'</h1><span>Membre depuis le '+esc(since)+'</span>'
 +'<div class="profile-level"><b>NIVEAU '+String(p.level).padStart(2,'0')+'</b><div class="progress" role="progressbar" aria-label="Progression du niveau" aria-valuemin="0" aria-valuemax="'+p.xpToNext+'" aria-valuenow="'+p.currentXp+'"><i style="width:'+xpPct+'%"></i></div><small>'+money(p.currentXp)+' / '+money(p.xpToNext)+' XP</small></div></div>'
 +'<div class="profile-actions"><a class="btn btn-gold" href="#vault">MON VAULT</a><a class="btn btn-outline" href="#collection">MA COLLECTION</a></div></section>'
 +'<section class="profile-kpis">'+kpi('CARTES',money(c.cards),money(c.unique)+' joueurs différents')+kpi('CLUBS',money(c.clubs),'représentés dans ta collection')+kpi('PACKS OUVERTS',money(p.packsOpened),'depuis ton inscription')+kpi('FOOTCOINS',money(Math.max(0,p.coins-p.reservedCoins)),p.reservedCoins?money(p.reservedCoins)+' réservés':'disponibles')+'</section>'
 +favoriteShowcase(d.favorites||[])
 +'<div class="profile-grid">'
 +'<section class="profile-panel"><p class="eyebrow">COLLECTION</p><h2>RARETÉS</h2><div class="profile-bars">'+c.rarities.map(r=>'<div class="profile-bar"><span>'+RL[r.rarity]+'</span><b>'+money(r.count)+'</b><div class="profile-track"><i class="r-'+r.rarity+'" style="width:'+(r.count/maxR*100)+'%"></i></div></div>').join('')+'</div>'
 +(c.best.length?'<h3>MEILLEURES CARTES</h3><ul class="profile-list">'+c.best.map(b=>'<li><a href="#card?id='+encodeURIComponent(b.id)+'"><span class="profile-li-main"><strong>'+esc(b.name)+'</strong><small>'+esc(b.club)+' · '+esc(b.season)+'</small></span><b class="profile-ovr r-'+esc(b.rarity)+'">'+b.ovr+'</b></a></li>').join('')+'</ul>':'')
 +(c.seasons.length?'<h3>SAISONS</h3><ul class="profile-list profile-seasons">'+c.seasons.map(s=>'<li><span>'+esc(s.season)+'</span><b>'+money(s.unique)+' joueur'+(s.unique>1?'s':'')+'</b></li>').join('')+'</ul>':'')+'</section>'
 +'<div class="profile-side"><section class="profile-panel"><p class="eyebrow">PROGRESSION</p><h2>PARCOURS</h2><div class="profile-stats">'
 +[['Succès obtenus',g.achievements],['Missions accomplies',g.missions],['Tâches récupérées',g.tasks],['Albums complétés',g.albums],['Ventes aux enchères',g.auctionsSold],['Enchères remportées',g.auctionsWon],['Ventes en cours',g.auctionsActive]].map(([l,v])=>'<div><span>'+l+'</span><b>'+money(v||0)+'</b></div>').join('')
 +'</div><a class="btn btn-ghost profile-more" href="#successes">VOIR MES SUCCÈS →</a></section>'
 +'<section class="profile-panel profile-history"><p class="eyebrow">HISTORIQUE</p><h2>MOUVEMENTS DE FOOTCOINS</h2>'
 +(h.length?'<ul class="profile-list">'+h.map(x=>'<li><span class="profile-li-main"><strong>'+esc(x.label)+'</strong><time datetime="'+esc(x.createdAt)+'">'+esc(when(x.createdAt))+'</time></span><b class="'+(x.amount>=0?'pos':'neg')+'">'+(x.amount>=0?'+':'−')+money(Math.abs(x.amount))+' FC</b></li>').join('')+'</ul>':'<p class="profile-empty">Aucun mouvement enregistré pour le moment.</p>')
 +'<p class="profile-note">Les 30 derniers mouvements. Historique tenu depuis le 30 septembre 2026.</p></section></div>'
 +'</div></div>';
}

// Carte d'un succès (page Succès) ; aussi utilisée telle quelle par l'aperçu de l'éditeur admin.
function successCard(x,featured=false){
 const pct=x=>Math.min(100,Math.round(Number(x.progress||0)/Math.max(1,Number(x.target)||1)*100));
 return '<article class="success-card '+(x.completed?'is-earned ':'')+(x.type==='secret'?'is-secret ':'')+(featured?'success-featured':'')+'" data-success-category="'+esc(x.category)+'" data-success-name="'+esc((x.name+' '+x.description+' '+x.category).toLowerCase())+'" data-success-claimable="'+(x.completed&&!x.claimed?'yes':'no')+'" data-success-progress="'+pct(x)+'" data-success-reward="'+Number(x.coins||0)+'"><div class="success-card-top"><span class="success-icon">'+esc(x.icon||'✦')+'</span><span class="success-status '+(x.claimed?'status-claimed':x.completed?'status-complete':'')+'">'+(x.claimed?'✓ RÉCOMPENSE RÉCUPÉRÉE':x.completed?'✓ TERMINÉ':'EN COURS')+'</span></div><p class="eyebrow">'+(x.code?'N° '+String(x.code).padStart(3,'0')+' · ':'')+esc(x.category).toUpperCase()+(x.hidden?' · SECRET':'')+'</p><h3>'+esc(x.name)+'</h3><p class="success-description">'+esc(x.description)+'</p>'+(x.type==='secret'?'<div class="success-progress success-progress-secret"><span>? / ?</span></div>':'<div class="success-progress"><div class="success-track"><i style="width:'+pct(x)+'%"></i></div><span>'+Math.min(Number(x.progress||0),Number(x.target||0)).toLocaleString('fr-FR')+' / '+Number(x.target||0).toLocaleString('fr-FR')+'</span></div>')+'<div class="success-reward"><span>RÉCOMPENSE</span><b><span>◉ '+Number(x.coins||0).toLocaleString('fr-FR')+' FC</span><span>✦ '+Number(x.xp||0).toLocaleString('fr-FR')+' XP</span></b></div>'+(x.completed&&!x.claimed?'<button class="btn btn-gold success-claim-btn" data-claim-achievement="'+esc(x.id)+'">RÉCUPÉRER LA RÉCOMPENSE <span>→</span></button>':'')+'</article>';
}
window.fvSuccessCard=successCard;

async function achievements(){
 let d,profile=null;
 try{[d,profile]=await Promise.all([api('/api/achievements'),api('/api/progression').catch(()=>null)])}
 catch(e){if(e.status===401)return authView('login','successes');throw e}
 const all=d.achievements||[],earned=all.filter(x=>x.completed).length,claimable=all.filter(x=>x.completed&&!x.claimed).length;
 const cats=['Tous',...new Set(all.map(x=>x.category))];
 const p=profile||{},user=p.user||{},xpPct=Math.min(100,p.xpToNext?Math.round(Number(p.currentXp||0)/Number(p.xpToNext)*100):0);
 const pct=x=>Math.min(100,Math.round(Number(x.progress||0)/Math.max(1,Number(x.target)||1)*100));
 const card=successCard;
 // À la une : d'abord les récompenses à récupérer, puis les succès les plus avancés (hors secrets).
 const featured=[...all.filter(x=>x.completed&&!x.claimed),...all.filter(x=>!x.completed&&x.type!=='secret').sort((a,b)=>pct(b)-pct(a))].slice(0,3);
 return '<div class="page success-page"><section class="success-hero"><div class="success-hero-copy"><p class="eyebrow">FOOTVAULT / TON PALMARÈS</p><h1>SUCCÈS <span>& MISSIONS</span></h1><p>Relève les défis, complète tes objectifs et débloque des récompenses uniques.</p><div class="success-hero-tags"><span>✦ COLLECTION</span><span>◈ PROGRESSION</span><span>♛ RÉCOMPENSES</span></div></div><div class="success-hero-mark"><div class="success-hero-shield"><span>♛</span></div><b>HALL<br>OF FAME</b><small>FOOTVAULT · 2026</small></div></section><section class="success-player-bar"><div class="success-player-id"><div class="success-level-badge"><small>NIVEAU</small><strong>'+String(p.level||1).padStart(2,'0')+'</strong></div><div class="success-player-copy"><strong>'+esc(user.username||user.displayName||'Ton profil')+'</strong><span>PROGRESSION DU COMPTE</span><div class="success-xp-track"><i style="width:'+xpPct+'%"></i></div><small>'+Number(p.currentXp||0).toLocaleString('fr-FR')+' / '+Number(p.xpToNext||0).toLocaleString('fr-FR')+' XP</small></div></div><div class="success-player-stat"><span>FOOTCOINS</span><strong>◉ '+Number(user.availableCoins??user.coins??0).toLocaleString('fr-FR')+'</strong></div><div class="success-player-stat"><span>NIVEAU</span><strong>✦ '+String(p.level||1).padStart(2,'0')+'</strong></div><div class="success-player-stat"><span>PROCHAINE ÉTAPE</span><strong>'+Math.max(0,Number(p.xpToNext||0)-Number(p.currentXp||0)).toLocaleString('fr-FR')+' XP</strong></div></section><section class="success-overview" id="successOverview"><article><span>SUCCÈS DÉBLOQUÉS</span><strong>'+earned+' <small>/ '+all.length+'</small></strong><div class="success-track"><i style="width:'+Math.round(earned/Math.max(1,all.length)*100)+'%"></i></div></article><article><span>CARTES COLLECTIONNÉES</span><strong>'+Number(d.cardCount||0).toLocaleString('fr-FR')+'</strong><small>Exemplaires dans ton Vault</small></article><article><span>RÉCOMPENSES DISPONIBLES</span><strong>'+claimable+'</strong><small>Succès prêts à être récupérés</small></article></section><nav class="success-tabs" aria-label="Navigation de progression"><a href="#vault">▦ MISSIONS</a><a href="#successes" class="active">♛ SUCCÈS</a><button type="button" data-success-view="rewards">♧ RÉCOMPENSES</button><button type="button" data-success-view="stats">▥ STATISTIQUES</button></nav><div class="success-toolbar"><div class="success-filter">'+cats.map((c,i)=>'<button class="success-filter-btn '+(!i?'active':'')+'" data-success-filter="'+esc(c)+'">'+esc(c)+(i===0?' ('+all.length+')':'')+'</button>').join('')+'</div><div class="success-tools"><label class="success-search"><span>⌕</span><input id="successSearch" type="search" placeholder="Rechercher un succès…" aria-label="Rechercher un succès"></label><select id="successSort" aria-label="Trier les succès"><option value="progress">Par progression</option><option value="name">Par nom</option><option value="reward">Par récompense</option></select></div></div><section class="success-feature-section"><div class="success-section-heading"><h2>✦ SUCCÈS À LA UNE</h2><span>'+featured.length+' À DÉCOUVRIR</span></div><div class="success-feature-grid">'+(featured.length?featured.map(x=>card(x,true)).join(''):'<div class="empty">Tous les succès à la une sont récupérés !</div>')+'</div></section><section class="success-all-section"><div class="success-section-heading"><h2>♛ TOUS LES SUCCÈS</h2><span>'+all.length+' DÉFIS</span></div><div class="success-grid">'+all.map(x=>card(x)).join('')+'</div><div class="success-no-results" id="successNoResults" hidden>Aucun succès ne correspond à ta recherche.</div></section></div>';
}

async function logout(){
 if(logout.busy)return; logout.busy=true;
 try{
  const r=await fetch('/api/logout',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}});
  if(!r.ok)throw new Error('La déconnexion a échoué.');
  state.user=null;state.cards=[];state.auctions=[];state.auctionHistory=[];
  toast('Déconnexion réussie.');
  location.hash='auth';
  await render();
 }catch(e){toast(e.message||'La déconnexion a échoué.')}finally{logout.busy=false}
}
async function daily(){try{const d=await api('/api/rewards/daily',{method:'POST'});state.user=d.user;toast(`+${d.reward.coins} FOOTCOINS · +${d.reward.xp} XP`+(d.streak>1?` · série de ${d.streak} jours`:''));render()}catch(e){toast(e.message)}}
