async function claimChallengeUi(id){try{const d=await api('/api/challenges/claim',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});toast('Défi réussi ! +'+money(d.reward.coins)+' FC · +'+money(d.reward.xp)+' XP');render()}catch(e){toast(e.message)}}
