function loadingSkeleton(){return '<div class="page page-loading" aria-busy="true" aria-label="Chargement"><div class="sk sk-hero"></div><div class="sk-row"><div class="sk"></div><div class="sk"></div><div class="sk"></div><div class="sk"></div></div><div class="sk sk-block"></div></div>'}
// Une page = une fonction (q : paramètres du lien) qui renvoie son HTML ; un module peut en remplacer une dans FVC.pages.
FVC.pages={home:()=>home(),collection:()=>collection(),packs:()=>packs(),vault:()=>vault(),profil:()=>profile(),classement:q=>ranking(q),successes:()=>achievements(),album:()=>album(),card:q=>cardDetail(q.get('id')),auth:q=>authView(q.get('mode')==='register'?'register':'login',q.get('next')||'vault'),...FVC.pages};
async function render(){shell();const {r,q}=route();let html='';const token=(state.renderToken=(state.renderToken||0)+1);const slow=state.renderedRoute!==r?setTimeout(()=>{if(state.renderToken===token)app().innerHTML=loadingSkeleton()},180):null;try{html=await(FVC.pages[r]||FVC.pages.home)(q);clearTimeout(slow);if(state.renderToken!==token)return;app().innerHTML=html;const viewKey=r+'|'+(q.get('id')||'');if(state.user&&state.viewedKey!==viewKey&&['album','card','classement','market'].includes(r))api('/api/activity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({page:r})}).catch(()=>{});state.viewedKey=viewKey;const prevRoute=state.renderedRoute;state.renderedRoute=r;document.title=(PAGE_TITLES[r]||'Accueil')+' — FOOTVAULT';if(prevRoute&&prevRoute!==r)app().focus({preventScroll:true});bind();nav();}catch(e){clearTimeout(slow);document.title=(PAGE_TITLES[r]||'Erreur')+' — FOOTVAULT';app().innerHTML=`<div class="page"><div class="empty"><h1>${esc(PAGE_TITLES[r]||'Erreur')}</h1><p>${esc(e.message)}</p></div></div>`}}
